/*
 * OpenLords2 — save-file I/O + schema table.
 * Port of retail FUN_004ade93 / FUN_004adfe6 / FUN_004ae8a9 /
 * FUN_004ae968 / FUN_004aea70 — see save.h for the address map and
 * docs/findings/save-format.md for the schema map.
 *
 * The big-block globals declared in save.h are defined here in BSS;
 * the scalar tail and the schema table itself come from
 * save_schema_table.h (generated by tools/gen_save_schema.py).
 *
 * I/O is plain stdio (fopen/fread/fwrite/fseek) — host-portable so
 * the round-trip test can run under nix-host gcc + ASan/UBSan
 * without dragging in Win32.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

#include "engine.h"
#include "engine_tile.h"
#include "save.h"

/* Big-block storage (entries 0..12).  See save.h for the address-to-
 * meaning map.  All zero-initialised; populated by save_load. */
uint8_t g_overworld_map         [32768];
uint8_t g_castles_state         [51200];
uint8_t g_player_aux_44         [  264];
uint8_t g_player_strategic_352  [ 2112];
uint8_t g_per_army_768          [13056];
uint8_t g_per_territory_420     [63420];
uint8_t g_unit_table_20         [  260];
uint8_t g_per_battle_hex_432    [34992];
uint8_t g_per_combat_unit_76    [ 7676];
uint8_t g_per_battle_hex_aux_52 [ 4212];
uint8_t g_castles_shadow        [51200];
uint8_t g_misc_128              [  128];
uint8_t g_misc_1360             [ 1360];

uint8_t g_castles_scratch       [CASTLES_BLOCK_BYTES];

/* Runtime tile scratches — see save.h for the retail-VA map. */
uint16_t g_path_scratch          [6400];
uint8_t  g_stage_scratch         [6400];

/* Recent-footprint list storage (160 B = schema slot 110 at 0x00553c80).
 * Overlaid by the g_footprint_list / g_last_footprint_tile macros in
 * save.h. */
uint8_t g_footprint_storage_160  [160];

/* Player roster (schema slot 140 at 0x568db0).  12 B runtime, only the
 * leading 6 B persisted — see save.h / engine_roster.c. */
uint8_t g_player_roster          [ 12];

/* Pulls in the scalar-tail storage + the schema table. */
#include "save_schema_table.h"

/* ------------------------------------------------------------------ */
/*  Save / load                                                       */
/* ------------------------------------------------------------------ */

/* Match retail's loop shape: walk entries 0..0xe1 (= 225), stop early
 * on a zero-size entry.  None of our 225 entries are zero, but the
 * terminator semantics are preserved for fidelity. */

int save_write(const char *sav_path, const char *castles_path)
{
    if (!sav_path || !castles_path) return 1;

    FILE *out = fopen(sav_path, "wb");
    if (!out) return 1;

    FILE *castles = fopen(castles_path, "rb");
    if (!castles) { fclose(out); return 1; }

    /* Block 1: serialize the 225-entry schema table. */
    for (int i = 0; i < SAVE_SCHEMA_COUNT; ++i) {
        uint32_t sz = g_save_schema[i].size;
        if (sz == 0) break;  /* retail terminator */
        if (fwrite(g_save_schema[i].ptr, 1, sz, out) != sz) {
            fclose(castles); fclose(out);
            return 1;
        }
    }

    /* Block 2: copy all 16 castle blocks verbatim from Castles.dat. */
    for (int b = 1; b <= CASTLES_BLOCK_COUNT; ++b) {
        if (fread(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, castles)
                != CASTLES_BLOCK_BYTES) {
            fclose(castles); fclose(out);
            return 1;
        }
        if (fwrite(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, out)
                != CASTLES_BLOCK_BYTES) {
            fclose(castles); fclose(out);
            return 1;
        }
    }

    fclose(castles);
    if (fclose(out) != 0) return 1;
    return 0;
}

int save_load(const char *sav_path, const char *castles_path)
{
    if (!sav_path || !castles_path) return 1;

    FILE *in = fopen(sav_path, "rb");
    if (!in) return 1;

    FILE *castles = fopen(castles_path, "wb");
    if (!castles) { fclose(in); return 1; }

    /* Block 1: deserialize the 225-entry schema table. */
    for (int i = 0; i < SAVE_SCHEMA_COUNT; ++i) {
        uint32_t sz = g_save_schema[i].size;
        if (sz == 0) break;
        if (fread(g_save_schema[i].ptr, 1, sz, in) != sz) {
            fclose(castles); fclose(in);
            return 1;
        }
    }

    /* Block 2: copy all 16 castle blocks from the .sav tail back into
     * Castles.dat (overwriting any prior contents). */
    for (int b = 1; b <= CASTLES_BLOCK_COUNT; ++b) {
        if (fread(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, in)
                != CASTLES_BLOCK_BYTES) {
            fclose(castles); fclose(in);
            return 1;
        }
        if (fwrite(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, castles)
                != CASTLES_BLOCK_BYTES) {
            fclose(castles); fclose(in);
            return 1;
        }
    }

    fclose(in);
    if (fclose(castles) != 0) return 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Turn-save backup rotation                                         */
/* ------------------------------------------------------------------ */

/* save_rotate_and_write — retail FUN_0049a453 @ 0x49a453.
 *
 * Rotate the 3-generation turn-save backup chain, then write the
 * current turn's "lastturn" save.  Retail calls this from new-game
 * setup and the turn-end handler.
 *
 * The filename family is chosen by the MP flags (retail's branch on
 * DAT_00553030 / DAT_00553248):
 *
 *   single-player  (g_sim_mp_active == 0)   →  *.sav
 *   MP, g_sim_mp_variant == 0               →  *.svb
 *   MP, g_sim_mp_variant != 0               →  *.sva
 *
 * Three generations, newest → oldest:
 *   lastturn.*  — the turn we're about to write
 *   old_turn.*  — previous turn
 *   safeturn.*  — two turns ago
 *
 * When the rotation-hold counter is clear (g_sim_save_rotate_hold < 1 —
 * always so in SP), rotate the chain first, dropping the oldest:
 *   remove(safeturn);  rename(old_turn → safeturn);  rename(lastturn → old_turn);
 * then always save_write(lastturn).  When the hold counter is set (only
 * on the MP turn-advance path) rotation is skipped and lastturn is just
 * overwritten in place.
 *
 * The filenames are bare relative paths exactly as retail builds them
 * (retail save_write chdir's to the base dir first, via 0x4af502);
 * callers are expected to be in the save directory.  retail ignores
 * every return value (remove / rename / FUN_004ade93) and is void; the
 * remove/rename are best-effort — a missing backup (the first save of a
 * game) is not an error.  We surface save_write's status as the return
 * for host-test observability; the rotation results stay unchecked, as
 * in retail.  See docs/findings/save-format.md. */
int save_rotate_and_write(const char *castles_path)
{
    const char *lastturn, *old_turn, *safeturn;

    if (g_sim_mp_active == 0) {
        lastturn = "lastturn.sav";
        old_turn = "old_turn.sav";
        safeturn = "safeturn.sav";
    } else if (g_sim_mp_variant == 0) {
        lastturn = "lastturn.svb";
        old_turn = "old_turn.svb";
        safeturn = "safeturn.svb";
    } else {
        lastturn = "lastturn.sva";
        old_turn = "old_turn.sva";
        safeturn = "safeturn.sva";
    }

    if (g_sim_save_rotate_hold < 1) {
        remove(safeturn);            /* drop the oldest backup       */
        rename(old_turn, safeturn);  /* previous turn → oldest        */
        rename(lastturn, old_turn);  /* last turn     → previous      */
    }

    return save_write(lastturn, castles_path);
}

/* ------------------------------------------------------------------ */
/*  Castles.dat helpers                                               */
/* ------------------------------------------------------------------ */

int castles_init_blank(const char *castles_path)
{
    if (!castles_path) return 1;
    FILE *f = fopen(castles_path, "wb");
    if (!f) return 1;
    for (size_t i = 0; i < CASTLES_BLOCK_BYTES; ++i)
        g_castles_scratch[i] = 0;
    for (int b = 1; b <= CASTLES_BLOCK_COUNT; ++b) {
        if (fwrite(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, f)
                != CASTLES_BLOCK_BYTES) {
            fclose(f);
            return 1;
        }
    }
    if (fclose(f) != 0) return 1;
    return 0;
}

/* castles_write_scenario — pack the live 6400 × 8 B in-memory castle
 * table down to 6400 × 2 B (only bytes +1 and +3 survive), seek to
 * the scenario's slot, write 12800 B.  Retail FUN_004ae968 uses
 * mode `O_RDWR | O_CREAT` (0x8101) so the file must exist (created
 * by castles_init_blank earlier in the boot path).
 *
 * Scenario indices are 1..16; the seek offset is (idx - 1) * 0x3200. */
int castles_write_scenario(const char *castles_path, int scenario_idx)
{
    if (!castles_path) return 1;
    if (scenario_idx < 1 || scenario_idx > CASTLES_BLOCK_COUNT) return 1;

    /* Pack 8-B records → 2-B records. */
    int j = 0;
    for (int i = 0; i < CASTLES_BLOCK_BYTES; i += 2) {
        g_castles_scratch[i    ] = g_castles_state[j + 3];  /* disk +0 = mem +3 */
        g_castles_scratch[i + 1] = g_castles_state[j + 1];  /* disk +1 = mem +1 */
        j += 8;
    }

    FILE *f = fopen(castles_path, "r+b");
    if (!f) return 1;
    long off = (long)(scenario_idx - 1) * (long)CASTLES_BLOCK_BYTES;
    if (fseek(f, off, SEEK_SET) != 0) { fclose(f); return 1; }
    if (fwrite(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, f)
            != CASTLES_BLOCK_BYTES) {
        fclose(f); return 1;
    }
    if (fclose(f) != 0) return 1;
    return 0;
}

/* castles_read_scenario — read 12800 B from the scenario slot, then
 * unpack the 6400 × 2 B disk records into 6400 × 8 B in-memory
 * records.  The unpack also applies post-load fixups based on the
 * existing mem +7 byte (= retail `DAT_005440e7`):
 *
 *   flags bit 1 (mask 0x02)  →  force mem +7 = 9, mem +4 = 0,
 *                               mem +2 &= 0xe3, mem +2 |= 4
 *   flags bit 0 (mask 0x01)  →  engine_tile_expand_footprint_at(j, ...)
 *                               (lay down 3x3 footprint, refresh path/
 *                                stage scratches, record in footprint
 *                                list — only for cells with a recognized
 *                                anchor char in +3)
 *   flags == 0 + mem+7 == 2  →  force mem +7 = 1
 *   flags == 0 + mem+7 == 7  →  force mem +7 = 5, mem +4 = 0,
 *                               mem +2 &= 0xe3, mem +2 |= 4
 *
 * Note the read direction is asymmetric vs. the write: write packs
 * 6400 × 8 → 6400 × 2; read unpacks 6400 × 2 → 6400 × 8 with the
 * fixup logic above.  Round-trip (load → save → reload) preserves
 * the bytes that touch disk; the 6 runtime-only bytes per record
 * are unaffected by the disk round-trip. */
int castles_read_scenario(const char *castles_path, int scenario_idx)
{
    if (!castles_path) return 1;
    if (scenario_idx < 1 || scenario_idx > CASTLES_BLOCK_COUNT) return 1;

    FILE *f = fopen(castles_path, "rb");
    if (!f) return 1;
    long off = (long)(scenario_idx - 1) * (long)CASTLES_BLOCK_BYTES;
    if (fseek(f, off, SEEK_SET) != 0) { fclose(f); return 1; }
    if (fread(g_castles_scratch, 1, CASTLES_BLOCK_BYTES, f)
            != CASTLES_BLOCK_BYTES) {
        fclose(f); return 1;
    }
    fclose(f);

    int j = 0;
    for (int i = 0; i < CASTLES_BLOCK_BYTES; i += 2) {
        g_castles_state[j + 3] = g_castles_scratch[i    ];
        g_castles_state[j + 1] = g_castles_scratch[i + 1];

        uint8_t mem7  = g_castles_state[j + 7];
        uint8_t flags = g_castles_state[j + 1];

        if (flags & 0x02) {
            g_castles_state[j + 7]  = 9;
            g_castles_state[j + 4]  = 0;
            g_castles_state[j + 2] &= 0xe3;
            g_castles_state[j + 2] |= 0x04;
        } else if (flags & 0x01) {
            /* Mirror of retail's `FUN_004917dd(local_c)` call.  Returns
             * 0 if +3 holds an unrecognized anchor char — both retail and
             * us no-op that case (retail's helper early-returns; ours
             * returns 0 without modifying any state). */
            engine_tile_expand_footprint_at(
                j,
                g_castles_state,
                g_path_scratch,
                g_stage_scratch,
                g_footprint_list,
                &g_last_footprint_tile);
        }

        if (flags == 0) {
            if (mem7 == 2) {
                g_castles_state[j + 7] = 1;
            } else if (mem7 == 7) {
                g_castles_state[j + 7]  = 5;
                g_castles_state[j + 4]  = 0;
                g_castles_state[j + 2] &= 0xe3;
                g_castles_state[j + 2] |= 0x04;
            }
        }

        j += 8;
    }
    return 0;
}
